require_once __DIR__ . '/includes/auth.php';require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../config/schema.php';require_once __DIR__ . '/../includes/functions.php';ensureFullSchema($pdo);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$load=function()use($pdo,$id){$s=$pdo->prepare("SELECT l.*,s.nome AS servico_nome,s.duracao_minutos FROM leituras l LEFT JOIN servicos_baralho s ON s.id=l.servico_id WHERE l.id=?");$s->execute([$id]);return $s->fetch();};$r=$load();if(!$r)exit('Leitura não encontrada.');$pageTitle='Leitura #'.$id;$permit=['Nova','Confirmada','Agendada','Concluída','Cancelada'];$msg='';
